<?php use App\Domain\Transfers\TransferRules as Rules; ?>
<section class="admin-page-head"><div><p class="admin-kicker">M09 · INVENTARIO ENTRE SUCURSALES</p><h1>Transferencias</h1><p>Solicitud, aprobación, tránsito y recepción física.</p></div><?php if($canCreate):?><a class="admin-primary-button" href="/admin/transfers/create">+ Solicitar transferencia</a><?php endif?></section>
<form class="admin-panel admin-filter-bar" method="get"><label class="admin-field"><span>Folio o sucursal</span><input name="q" value="<?= e($q) ?>" maxlength="120"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><option value="">Todas autorizadas</option><?php foreach($branches as $b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="">Todos</option><?php foreach(Rules::LABELS as $key=>$label):?><option value="<?= e($key) ?>" <?= $status===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach?></select></label><button class="admin-secondary-button">Filtrar</button></form>
<section class="admin-panel admin-table-panel"><?php if(!$page->items):?><div class="admin-empty"><strong>No hay transferencias</strong><span>Las solicitudes no generan movimientos físicos.</span></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Folio / fecha</th><th>Origen</th><th>Destino</th><th>Estado</th><th>Responsable</th><th>Partidas</th><th></th></tr></thead><tbody><?php foreach($page->items as $t):?><tr><td data-label="Folio / fecha"><?= e($t['folio']) ?><small><?= e($t['created_at']) ?> UTC</small></td><td data-label="Origen"><?= e($t['source_name']) ?></td><td data-label="Destino"><?= e($t['destination_name']) ?></td><td data-label="Estado"><?= e(Rules::LABELS[$t['status']]) ?></td><td data-label="Responsable"><?= e($t['actor_name']) ?></td><td data-label="Partidas"><?= e($t['item_count']) ?></td><td><a class="admin-secondary-button" href="/admin/transfers/detail?id=<?= e($t['id']) ?>">Abrir</a></td></tr><?php endforeach?></tbody></table></div><?php endif?><nav class="admin-pagination" aria-label="Paginación"><?php $params=['q'=>$q,'status'=>$status,'branch_id'=>$branchId];if($page->offset>0):?><a href="?<?= e(http_build_query($params+['offset'=>max(0,$page->offset-25)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a href="?<?= e(http_build_query($params+['offset'=>$page->offset+25])) ?>">Siguiente</a><?php endif?></nav></section>
